//-------------------------------------------------
// Defines for LowpassSpectral API's.
//-------------------------------------------------

#define LowpassSpectral_OFF                      (0x00)
#define LowpassSpectral_LOWPOWER                 (0x01)
#define LowpassSpectral_MEDPOWER                 (0x02)
