#define LowpassSpectral_FEEDBACK_16              (0x00)
#define LowpassSpectral_FEEDBACK_32              (0x01)

#define LowpassSpectral_POLARITY_INVERTING       (0x00)
#define LowpassSpectral_POLARITY_NON_INVERTING   (0x01)

#define LowpassSpectral_AMD_MSK      (0x70)
#define LowpassSpectral_AMD_VAL      (0x0)

